import{_ as n,a0 as i,w as s,s as d,I as e,x as t,a1 as o,A as l,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"12-Factor 應用方法論的開源開發者指南 | LCTT x X-CMD","titleTemplate":false,"description":"12-Factor 應用方法論的開源開發者指南 | LCTT (202311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"12-Factor 應用方法論的開源開發者指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"12-Factor 應用方法論的開源開發者指南 | LCTT (202311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202311/20220113 An open source developer-s guide to 12-Factor App methodology","title":"12-Factor 應用方法論的開源開發者指南","tag":"202311","desc":""},"relativePath":"202311/20220113 An open source developer-s guide to 12-Factor App methodology.md","filePath":"[post].md"}'),u={name:"202311/20220113 An open source developer-s guide to 12-Factor App methodology.md"};function m(f,a,h,b,T,_){const r=i("Link");return s(),d("div",null,[a[27]||(a[27]=e("h1",{id:"_12-factor-應用方法論的開源開發者指南",tabindex:"-1"},[t("12-Factor 應用方法論的開源開發者指南 "),e("a",{class:"header-anchor",href:"#_12-factor-應用方法論的開源開發者指南","aria-label":"Permalink to “12-Factor 應用方法論的開源開發者指南”"},"​")],-1)),a[28]||(a[28]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202311/16/124441qs8hltth7hurdzos.png",alt:""})],-1)),a[29]||(a[29]=e("blockquote",null,[e("p",null,"這 12 項基本原則能夠幫助團隊快速高效地構建高度可擴展的應用程序")],-1)),e("p",null,[o(r,{href:"https://www.redhat.com/architect/12-factor-app"},{default:l(()=>[...a[0]||(a[0]=[t("12-Factor 應用方法論",-1)])]),_:1}),a[1]||(a[1]=t(" 為在短時間內構建應用程序並使其具有可擴展性提供了指導。它由 Heroku 的開發人員創建，用於軟件即服務（SaaS）應用程序、網絡應用程序以及可能的通信平台即服務（CPaaS）。在有效組織項目和管理可擴展應用程序方面，12 要素應用程序方法論對開源開發具有強大的優勢。",-1))]),a[30]||(a[30]=p('<h3 id="_12-factor-應用方法論的原則" tabindex="-1">12-Factor 應用方法論的原則 <a class="header-anchor" href="#_12-factor-應用方法論的原則" aria-label="Permalink to “12-Factor 應用方法論的原則”">​</a></h3><p>12-Factor 應用方法論的規則非常嚴格，也是開發和部署 SaaS 應用程序的基石，並且不受任何編程語言或資料庫的限制。</p><h4 id="_1-一份基準代碼-多份部署" tabindex="-1">1：一份基準代碼，多份部署 <a class="header-anchor" href="#_1-一份基準代碼-多份部署" aria-label="Permalink to “1：一份基準代碼，多份部署”">​</a></h4><p><img src="https://opensource.com/sites/default/files/uploads/codebase-deploy_1.png" alt="一個説明圖表：顯示了一個由左邊的綠線代表的代碼庫，引導到右邊由綠色方塊代表的四個部署。橙色方塊代表暫存環境，而紅色方塊代表生產環境。" title="Codebase"></p><p>每個應用程序都應該有一個具有多個不同環境/部署的代碼庫。</p><p>開發人員不應僅僅為了在不同環境中設置而開發另一個代碼庫。不同的環境代表不同的狀態，但這些不同的環境應該共享同一個代碼庫。</p><p>在許多開源項目都存儲在 GitLab 這樣的版本控制系統中的情況下，一個環境可以被視為一個分支。例如，你可以在任何中央版本控制系統中為名為 VoIP-app 的雲 VoIP 應用程序創建一個單獨的存儲庫，然後創建兩個分支：開發分支（<code>development</code>）和暫存分支（<code>staging</code>），並將主分支（<code>master</code>）作為發佈分支。</p><h4 id="_2-明確聲明和隔離依賴關係" tabindex="-1">2：明確聲明和隔離依賴關係 <a class="header-anchor" href="#_2-明確聲明和隔離依賴關係" aria-label="Permalink to “2：明確聲明和隔離依賴關係”">​</a></h4><p>應聲明所有依賴關係。你的應用程序可能會依賴外部系統工具或庫，但不應對系統工具或庫有任何 <em>隱含的</em> 依賴。你的應用程序必須始終明確聲明所有依賴關係及其正確版本。</p><p>在代碼庫中包含依賴關係可能會產生問題，特別是在開源項目中，外部庫的更改可能會將錯誤引入代碼庫。例如，代碼庫可能會使用一個外部庫，但沒有明確聲明該依賴關係或版本。如果外部庫更新到更新的、未經測試的版本，這可能會與你的代碼產生兼容性問題。如果明確聲明瞭依賴關係及其正確版本，你的代碼庫就不會出現這種問題。</p><p>根據技術棧的不同，最好使用軟件包管理器，通過讀取代表依賴庫名稱和版本的依賴庫聲明清單，在各自的系統上下載依賴庫。</p><h4 id="_3-在環境中存儲配置" tabindex="-1">3：在環境中存儲配置 <a class="header-anchor" href="#_3-在環境中存儲配置" aria-label="Permalink to “3：在環境中存儲配置”">​</a></h4><p>當需要支持多個環境或客户端時，配置就成了應用程序的重要組成部分。不同部署之間的配置應存儲在環境變量中。這樣就可以在部署之間輕鬆更改配置，而無需更改代碼。</p><p>對於閉源應用程序來説，這一原則是有益的，因為你不會希望資料庫連接信息或其他秘密數據等敏感信息被公開。然而，在開放源代碼開發中，這些細節都是公開的。在這種情況下，好處是你不需要反覆修改代碼。你只需這樣設置變量，只需改變環境，就能讓代碼完美運行。</p><h4 id="_4-把後端服務當作附加資源" tabindex="-1">4：把後端服務當作附加資源 <a class="header-anchor" href="#_4-把後端服務當作附加資源" aria-label="Permalink to “4：把後端服務當作附加資源”">​</a></h4><p>所有後備服務（如資料庫、外部存儲或消息隊列）都被視為附加資源，由執行環境附加或分離。根據這一原則，如果這些服務的位置或連接細節發生變化，仍無需更改代碼。這些細節可以在配置中找到。</p><p>備份服務可以從部署中快速附加或分離。例如，如果基於雲的電子表格的資料庫無法正常工作，開發人員應該能夠創建一個從最近備份恢復的新資料庫服務器，而無需對代碼庫進行任何更改。</p><h4 id="_5-嚴格分離構建和運行" tabindex="-1">5：嚴格分離構建和運行 <a class="header-anchor" href="#_5-嚴格分離構建和運行" aria-label="Permalink to “5：嚴格分離構建和運行”">​</a></h4><p>12-Factor 應用方法論要求嚴格區分構建、發佈和運行階段。</p><ul><li>第一階段是 <em>構建</em> 階段。在這一階段，源代碼被組裝或編譯成可執行文件，同時加載依賴關係並創建資產。每次需要部署新代碼時，構建階段就會開始。</li><li>第二階段是 <em>發佈</em> 階段。在此階段，構建階段生成的代碼與部署的當前配置相結合。最終發佈的版本包含構建和配置，可在執行環境中立即執行。</li><li>第三個階段是 <em>運行</em> 階段，也是最後階段：應用程序在執行環境中運行。該階段不應被其他任何階段打斷。</li></ul><p>通過嚴格區分這些階段，我們可以避免代碼中斷，使系統維護更加易於管理。</p><h4 id="_6-以一個或多個無狀態進程運行應用" tabindex="-1">6：以一個或多個無狀態進程運行應用 <a class="header-anchor" href="#_6-以一個或多個無狀態進程運行應用" aria-label="Permalink to “6：以一個或多個無狀態進程運行應用”">​</a></h4><p>應用程序作為一個或多個進程的集合在執行環境中執行。這些進程是無狀態的，其持久化數據存儲在資料庫等後台服務中。</p><p>這對開源非常有用，因為使用某版本應用程序的開發人員可以在其雲平台上創建多節點部署，以實現可擴展性。數據不會在其中持久化，因為如果其中任何一個節點崩潰，數據就會丟失。</p><h4 id="_7-通過端口綁定提供服務" tabindex="-1">7：通過端口綁定提供服務 <a class="header-anchor" href="#_7-通過端口綁定提供服務" aria-label="Permalink to “7：通過端口綁定提供服務”">​</a></h4>',25)),e("p",null,[a[3]||(a[3]=t("你的應用程序應作為獨立的服務，獨立於其他應用程序。它它應該能通過URL供其他服務訪問，以服務形式存在。這樣，你的應用程序就可以在需要時作為其他應用程序的資源。利用這一概念，你可以構建 ",-1)),o(r,{href:"https://opensource.com/article/21/9/ansible-rest-apis"},{default:l(()=>[...a[2]||(a[2]=[t("REST API",-1)])]),_:1}),a[4]||(a[4]=t("。",-1))]),a[31]||(a[31]=p('<h4 id="_8-通過進程模型進行擴展" tabindex="-1">8：通過進程模型進行擴展 <a class="header-anchor" href="#_8-通過進程模型進行擴展" aria-label="Permalink to “8：通過進程模型進行擴展”">​</a></h4><p>該原則也稱為併發原則，它表明應用程序中的每個進程都應能夠自我擴展、重啓或克隆。</p><p>開發人員可以創建多個進程，並將應用程序的負載分配給這些進程，而不是將一個進程變大。通過這種方法，你可以將每種工作負載分配給一個進程類型，從而構建能處理不同工作負載的應用程序。</p><h4 id="_9-快速啓動和優雅終止以增強健壯性" tabindex="-1">9：快速啓動和優雅終止以增強健壯性 <a class="header-anchor" href="#_9-快速啓動和優雅終止以增強健壯性" aria-label="Permalink to “9：快速啓動和優雅終止以增強健壯性”">​</a></h4><p>你的應用應當基於簡單的進程構建，因此開發者可以放大進程的同時還能在發生問題時重啓它們。這使得應用的進程易於丟棄。</p><p>根據這一原則構建應用程序意味着代碼的快速部署、快速彈性擴展、更靈活的發佈流程以及穩健的生產部署。所有這些在開源開發環境中都非常有用。</p><h4 id="_10-儘可能的保持開發、預發佈、生產環境相同" tabindex="-1">10：儘可能的保持開發、預發佈、生產環境相同 <a class="header-anchor" href="#_10-儘可能的保持開發、預發佈、生產環境相同" aria-label="Permalink to “10：儘可能的保持開發、預發佈、生產環境相同”">​</a></h4><p>同一項目的團隊應使用相同的操作系統、支持服務和依賴關係。這樣可以降低出現錯誤的可能性，減少開發所需的時間。</p>',8)),e("p",null,[a[6]||(a[6]=t("由於開源項目的開發人員分散在各地，他們可能無法就所使用的系統、服務和依賴關係進行 ",-1)),o(r,{href:"https://opensource.com/article/21/10/global-communication-open-source"},{default:l(()=>[...a[5]||(a[5]=[t("溝通",-1)])]),_:1}),a[7]||(a[7]=t(" ，因此將這一原則付諸實踐對於開源項目來説可能是一個挑戰。減少這些差異的一種可能性是制定開發指南，建議使用何種操作系統、服務和依賴關係。",-1))]),a[32]||(a[32]=p('<h4 id="_11-把日誌當作事件流" tabindex="-1">11：把日誌當作事件流 <a class="header-anchor" href="#_11-把日誌當作事件流" aria-label="Permalink to “11：把日誌當作事件流”">​</a></h4><p>日誌對於排除生產問題或瞭解用户行為至關重要。但是，12-Factor 應用方法論並不適合處理日誌的管理。</p><p>相反，應將日誌條目作為事件流，寫入標準輸出，並將其發送到單獨的服務進行分析和存檔。機器人流程自動化（RPA）技術可作為處理和分析日誌的第三方服務。執行環境將決定如何處理該數據流。這為反省應用程序的行為提供了更大的靈活性和能力。</p><h4 id="_12-後台管理任務當作一次性進程運行" tabindex="-1">12：後台管理任務當作一次性進程運行 <a class="header-anchor" href="#_12-後台管理任務當作一次性進程運行" aria-label="Permalink to “12：後台管理任務當作一次性進程運行”">​</a></h4><p>這一原則實際上與開發無關，而是與應用程序管理有關。管理進程應在與應用程序常規長期運行進程相同的環境中運行。在本地部署中，開發人員可以直接使用應用程序簽出目錄內的 Shell 命令來執行一次性管理進程。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>使用 12-Factor 應用方法論開發應用程序，可以提高效率，加快發佈速度。在開源開發中，偏離某些指導原則可能是有意義的，但最好還是儘可能嚴格遵守這些指導原則。</p>',7)),e("p",null,[a[10]||(a[10]=t("開源的 12-Factor 應用是可能的。一個很好的例子是 ",-1)),o(r,{href:"https://jitsi.org/"},{default:l(()=>[...a[8]||(a[8]=[t("Jitsi",-1)])]),_:1}),o(r,{href:"http://jitsi.org"},{default:l(()=>[...a[9]||(a[9]=[t(", （一個開源視頻會議平台）",-1)])]),_:1}),a[11]||(a[11]=t(", 在疫情期間擴展了 100 倍的規模，取得了巨大成功，它就是採用 12-Factor 應用方法論構建的。",-1))]),a[33]||(a[33]=e("p",null,[e("em",null,"（題圖：MJ/4bc8b463-49d0-4702-8ad3-6a07a718d5d9）")],-1)),a[34]||(a[34]=e("hr",null,null,-1)),e("p",null,[a[13]||(a[13]=t("via: ",-1)),o(r,{href:"https://opensource.com/article/21/11/open-source-12-factor-app-methodology"},{default:l(()=>[...a[12]||(a[12]=[t("https://opensource.com/article/21/11/open-source-12-factor-app-methodology",-1)])]),_:1})]),e("p",null,[a[18]||(a[18]=t("作者：",-1)),o(r,{href:"https://opensource.com/users/richardaconn-0"},{default:l(()=>[...a[14]||(a[14]=[t("Richard Conn",-1)])]),_:1}),a[19]||(a[19]=t(" 選題：",-1)),o(r,{href:"https://github.com/lujun9972"},{default:l(()=>[...a[15]||(a[15]=[t("lujun9972",-1)])]),_:1}),a[20]||(a[20]=t(" 譯者：",-1)),o(r,{href:"https://github.com/trisbestever"},{default:l(()=>[...a[16]||(a[16]=[t("trisbestever",-1)])]),_:1}),a[21]||(a[21]=t(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:l(()=>[...a[17]||(a[17]=[t("wxy",-1)])]),_:1})]),e("p",null,[a[24]||(a[24]=t("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[22]||(a[22]=[t("LCTT",-1)])]),_:1}),a[25]||(a[25]=t(" 原創編譯，",-1)),o(r,{href:"https://linux.cn/"},{default:l(()=>[...a[23]||(a[23]=[t("Linux中國",-1)])]),_:1}),a[26]||(a[26]=t(" 榮譽推出",-1))])])}const C=n(u,[["render",m]]);export{P as __pageData,C as default};
